package bubble

import (
	"fmt"
	"github.com/charmbracelet/lipgloss"
	"gocode/internal/loop"
	"gocode/internal/settings"
	"math"
	"strconv"
	"strings"
	"time"
)

func (m appModel) contextMeterTitle() string {
	width := m.width
	if width <= 0 {
		width = contextMeterDefaultWidth
	}
	return m.contextMeterLine(maxInt(28, width-2))
}

func (m appModel) contextMeterLine(width int) string {
	stats := m.contextStats()
	limit := maxInt(1, stats.LimitTokens)
	rawUsed := maxInt(0, stats.UsedTokens)
	rawCache := clampInt(stats.CacheTokens, 0, rawUsed)
	// 进度条：easeOutBack（有轻微超出感，720ms）
	animatedUsed, animatedCache, pulse := m.animatedContextTokens(limit)
	// 标签数字：easeOutCubic（无超出，400ms），呈现快速计数跳动效果
	labelUsed, labelCache := m.animatedLabelTokens(rawUsed, rawCache, limit)
	usedLabel := formatContextUsageLabel(labelUsed, labelCache, limit, m.isGenerating)
	freeLabel := formatContextFreeLabel(labelUsed, limit)
	return renderContextMeterLine(width, usedLabel, freeLabel, animatedUsed, animatedCache, limit, m.thinkingLabel(), pulse)
}

func formatContextUsageLabel(used, cache, limit int, isGenerating bool) string {
	arrow := "↑"
	if isGenerating {
		arrow = "↓"
	}
	parts := []string{formatCompactTokenCount(used) + arrow}
	parts = append(parts, fmt.Sprintf("%s(%s)", formatContextPercent(used, limit), formatContextPercent(cache, limit)))
	return strings.Join(parts, " ")
}

func formatContextFreeLabel(used, limit int) string {
	free := maxInt(0, limit-used)
	return fmt.Sprintf("free(%s)", formatContextPercent(free, limit))
}

func formatContextPercent(value, total int) string {
	return fmt.Sprintf("%.0f%%", percent(clampInt(value, 0, maxInt(0, total)), total))
}

func formatCompactTokenCount(value int) string {
	value = maxInt(0, value)
	if value <= 999 {
		return strconv.Itoa(value)
	}
	scaled := float64(value) / 1000
	unit := "k"
	if value > 999000 {
		scaled = float64(value) / 1000000
		unit = "M"
	}
	text := formatThreeDigitNumber(scaled)
	if unit == "k" && strings.HasPrefix(text, "1000") {
		text = formatThreeDigitNumber(float64(value) / 1000000)
		unit = "M"
	}
	return text + unit
}

func formatThreeDigitNumber(value float64) string {
	switch {
	case value >= 100:
		return fmt.Sprintf("%.0f", value)
	case value >= 10:
		return trimTrailingDecimalZeros(fmt.Sprintf("%.1f", value))
	default:
		return trimTrailingDecimalZeros(fmt.Sprintf("%.2f", value))
	}
}

func trimTrailingDecimalZeros(text string) string {
	text = strings.TrimRight(text, "0")
	return strings.TrimRight(text, ".")
}

func (m appModel) contextStats() loop.ContextStats {
	cfg := m.currentSettings()
	limit := cfg.UI.ContextLimitTokens
	if provider, ok := m.runner.(contextStatsProvider); ok {
		return provider.ContextStats(limit, m.input.Value())
	}
	return loop.ContextStats{LimitTokens: limit}
}

func (m appModel) currentSettings() settings.Config {
	if m.settingsConfig == nil {
		return settings.DefaultConfig()
	}
	return settings.Normalize(m.settingsConfig.CurrentSettings())
}

func (m appModel) thinkingLabel() string {
	if !m.isModelWorkRunning() || m.turnStartedAt.IsZero() {
		return ""
	}
	now := m.cursorFrameAt
	if now.IsZero() {
		now = time.Now()
	}
	elapsed := now.Sub(m.turnStartedAt)
	if elapsed < 0 {
		elapsed = 0
	}
	return fmt.Sprintf("<thinking %ds>", int(elapsed.Seconds()))
}

func contextBarWidth(width int, usedLabel, freeLabel string) int {
	width = maxInt(1, width)
	barWidth := width - lipgloss.Width(usedLabel) - lipgloss.Width(freeLabel) - 2
	if barWidth >= 8 {
		return barWidth
	}
	return maxInt(contextMeterMinimumBarCells, width-lipgloss.Width(compactContextLabel(usedLabel))-lipgloss.Width(compactContextLabel(freeLabel))-2)
}

func compactContextLabel(label string) string {
	if strings.HasPrefix(label, "free(") {
		return "free"
	}
	fields := strings.Fields(label)
	if len(fields) == 0 {
		return label
	}
	if len(fields) <= 2 {
		return fields[0]
	}
	return strings.Join(fields[:2], " ")
}

func renderContextMeterLine(width int, usedLabel, freeLabel string, used, cache, limit int, overlay string, pulse float64) string {
	width = maxInt(1, width)
	barWidth := contextBarWidth(width, usedLabel, freeLabel)
	if barWidth+lipgloss.Width(usedLabel)+lipgloss.Width(freeLabel)+2 > width {
		usedLabel = compactContextLabel(usedLabel)
		freeLabel = compactContextLabel(freeLabel)
	}
	usedText := contextUsedStyle.Render(usedLabel)
	freeText := contextFreeStyle.Render(freeLabel)
	barWidth = maxInt(contextMeterMinimumBarCells, width-lipgloss.Width(usedLabel)-lipgloss.Width(freeLabel)-2)
	barOffset := lipgloss.Width(usedLabel) + 1
	overlayStart := centeredOverlayStart(width, barOffset, barWidth, overlay)
	bar := renderContextBarWithOverlayStart(used, cache, limit, barWidth, overlay, overlayStart, pulse)
	line := usedText + " " + bar + " " + freeText
	if visible := lipgloss.Width(line); visible < width {
		line += strings.Repeat(" ", width-visible)
	}
	return line
}

func renderContextBar(used, cache, limit, width int, overlay string) string {
	overlayStart := -1
	if overlayWidth := lipgloss.Width(overlay); overlayWidth > 0 && overlayWidth <= width {
		overlayStart = (width - overlayWidth) / 2
	}
	return renderContextBarWithOverlayStart(used, cache, limit, width, overlay, overlayStart, 0)
}

func renderContextBarWithOverlayStart(used, cache, limit, width int, overlay string, overlayStart int, pulse float64) string {
	limit = maxInt(1, limit)
	width = maxInt(contextMeterMinimumBarCells, width)
	usedCells := int(math.Round(float64(clampInt(used, 0, limit)) / float64(limit) * float64(width)))
	cacheCells := int(math.Round(float64(clampInt(cache, 0, used)) / float64(limit) * float64(width)))
	if cacheCells > usedCells {
		cacheCells = usedCells
	}
	cells := make([]string, width)
	for i := 0; i < width; i++ {
		switch {
		case i < cacheCells:
			cells[i] = contextCacheStyle.Render("▰")
		case i < usedCells:
			cells[i] = contextUsedPulseStyle(pulse, i, usedCells).Render("▰")
		default:
			cells[i] = contextFreeStyle.Render("▱")
		}
	}
	overlayRunes := []rune(overlay)
	if len(overlayRunes) > 0 && overlayStart >= 0 && overlayStart+len(overlayRunes) <= width {
		for i, r := range overlayRunes {
			cells[overlayStart+i] = contextThinkingStyle.Render(string(r))
		}
	}
	return strings.Join(cells, "")
}

func (m *appModel) updateContextMeterAnimation() {
	now := m.animationNow()
	stats := m.contextStats()
	limit := maxInt(1, stats.LimitTokens)
	used := clampInt(maxInt(0, stats.UsedTokens), 0, limit)
	cache := clampInt(stats.CacheTokens, 0, used)
	if !m.contextMeter.initialized {
		m.contextMeter = contextMeterAnimation{
			initialized: true,
			startedAt:   now,
			fromUsed:    float64(used),
			fromCache:   float64(cache),
			targetUsed:  used,
			targetCache: cache,
		}
		return
	}
	if m.contextMeter.targetUsed == used && m.contextMeter.targetCache == cache {
		return
	}
	currentUsed, currentCache, _ := m.animatedContextTokens(limit)
	m.contextMeter.startedAt = now
	m.contextMeter.fromUsed = float64(currentUsed)
	m.contextMeter.fromCache = float64(currentCache)
	m.contextMeter.targetUsed = used
	m.contextMeter.targetCache = cache
}

func (m appModel) animatedContextTokens(limit int) (int, int, float64) {
	if !m.contextMeter.initialized {
		return m.contextMeter.targetUsed, m.contextMeter.targetCache, 0
	}
	now := m.animationNow()
	elapsed := now.Sub(m.contextMeter.startedAt)
	if elapsed < 0 {
		elapsed = 0
	}
	const duration = 720 * time.Millisecond
	progress := clamp01(float64(elapsed) / float64(duration))
	eased := easeOutBack(progress)
	animatedUsed := int(math.Round(lerp(m.contextMeter.fromUsed, float64(m.contextMeter.targetUsed), eased)))
	animatedCache := int(math.Round(lerp(m.contextMeter.fromCache, float64(m.contextMeter.targetCache), eased)))
	animatedUsed = clampInt(animatedUsed, 0, limit)
	animatedCache = clampInt(animatedCache, 0, animatedUsed)
	return animatedUsed, animatedCache, contextPulse(progress)
}

// animatedLabelTokens 用 easeOutCubic + 400ms 为数字标签计算动画值。
// 动画未初始化时回退到 rawUsed/rawCache（立即显示真实值）。
func (m appModel) animatedLabelTokens(rawUsed, rawCache, limit int) (used, cache int) {
	if !m.contextMeter.initialized {
		return clampInt(rawUsed, 0, limit), clampInt(rawCache, 0, clampInt(rawUsed, 0, limit))
	}
	now := m.animationNow()
	elapsed := now.Sub(m.contextMeter.startedAt)
	if elapsed < 0 {
		elapsed = 0
	}
	const labelDuration = 400 * time.Millisecond
	progress := clamp01(float64(elapsed) / float64(labelDuration))
	eased := easeOutCubic(progress)
	animUsed := int(math.Round(lerp(m.contextMeter.fromUsed, float64(m.contextMeter.targetUsed), eased)))
	animCache := int(math.Round(lerp(m.contextMeter.fromCache, float64(m.contextMeter.targetCache), eased)))
	animUsed = clampInt(animUsed, 0, limit)
	animCache = clampInt(animCache, 0, animUsed)
	return animUsed, animCache
}

func contextPulse(progress float64) float64 {
	if progress <= 0 || progress >= 1 {
		return 0
	}
	return math.Sin(progress * math.Pi)
}

func contextUsedPulseStyle(pulse float64, index, usedCells int) lipgloss.Style {
	if pulse <= 0 || usedCells <= 0 || index < usedCells-2 {
		return contextUsedStyle
	}
	return contextUsedStyle.Copy().Foreground(colorManager.LipglossColor(colorMarkdownHeading)).Bold(true)
}

func lerp(from, to, t float64) float64 {
	return from + (to-from)*t
}

func easeOutBack(t float64) float64 {
	t = clamp01(t)
	const c1 = 1.70158
	const c3 = c1 + 1
	x := t - 1
	return 1 + c3*x*x*x + c1*x*x
}

func centeredOverlayStart(lineWidth, barOffset, barWidth int, overlay string) int {
	overlayWidth := lipgloss.Width(overlay)
	if overlayWidth == 0 || overlayWidth > barWidth {
		return -1
	}
	start := (lineWidth-overlayWidth)/2 - barOffset
	if start < 0 || start+overlayWidth > barWidth {
		return (barWidth - overlayWidth) / 2
	}
	return start
}

func percent(value, total int) float64 {
	if total <= 0 {
		return 0
	}
	return float64(value) / float64(total) * 100
}

func clampInt(value, minValue, maxValue int) int {
	if value < minValue {
		return minValue
	}
	if value > maxValue {
		return maxValue
	}
	return value
}

// 本文件定义 TUI 颜色管理器，集中维护主题色和光标颜色。
package bubble

import (
	"fmt"
	"strconv"
	"strings"

	"github.com/charmbracelet/lipgloss"
)

// colorRole 表示一个可复用的颜色语义角色。
type colorRole string

// 颜色语义角色常量。
const (
	colorTerminalBackground     colorRole = "terminal.background"
	colorHeaderBackground       colorRole = "header.background"
	colorHeaderForeground       colorRole = "header.foreground"
	colorLabelUser              colorRole = "label.user"
	colorLabelAssistant         colorRole = "label.assistant"
	colorLabelTool              colorRole = "label.tool"
	colorLabelSystem            colorRole = "label.system"
	colorLabelError             colorRole = "label.error"
	colorBody                   colorRole = "body"
	colorMarkdownHeading        colorRole = "markdown.heading"
	colorMarkdownRule           colorRole = "markdown.rule"
	colorMarkdownBullet         colorRole = "markdown.bullet"
	colorMarkdownCodeForeground colorRole = "markdown.code.foreground"
	colorMarkdownCodeBackground colorRole = "markdown.code.background"
	colorMarkdownCodeBorder     colorRole = "markdown.code.border"
	colorMarkdownQuote          colorRole = "markdown.quote"
	colorMarkdownQuoteBorder    colorRole = "markdown.quote.border"
	colorPanelBorder            colorRole = "panel.border"
	colorInputFocusedBorder     colorRole = "input.focused.border"
	colorInputWaitingBorder     colorRole = "input.waiting.border"
	colorInputMultilineBorder   colorRole = "input.multiline.border"
	colorInputTerminal          colorRole = "input.terminal"
	colorSelectedProviderBg     colorRole = "provider.selected.background"
	colorSelectedProviderFg     colorRole = "provider.selected.foreground"
	colorUnselectedProvider     colorRole = "provider.unselected"
	colorWizardTitle            colorRole = "wizard.title"
	colorWizardBorder           colorRole = "wizard.border"
	colorSelectionBackground    colorRole = "selection.background"
	colorSelectionForeground    colorRole = "selection.foreground"
	colorContextCache           colorRole = "context.cache"
	colorContextUsed            colorRole = "context.used"
	colorContextFree            colorRole = "context.free"
	colorCursorNormalBright     colorRole = "cursor.normal.bright"
	colorCursorTerminalBright   colorRole = "cursor.terminal.bright"
)

// ColorManager 集中管理 Bubble Tea TUI 的颜色调色板。
type ColorManager struct {
	palette map[colorRole]string
}

// colorManager 是当前 TUI 使用的默认颜色管理器。
var colorManager = NewColorManager()

// NewColorManager 创建默认颜色管理器。
func NewColorManager() ColorManager {
	return ColorManager{
		palette: map[colorRole]string{
			colorTerminalBackground:     "#292C33",
			colorHeaderBackground:       "236",
			colorHeaderForeground:       "231",
			colorLabelUser:              "86",
			colorLabelAssistant:         "111",
			colorLabelTool:              "214",
			colorLabelSystem:            "245",
			colorLabelError:             "203",
			colorBody:                   "252",
			colorMarkdownHeading:        "229",
			colorMarkdownRule:           "240",
			colorMarkdownBullet:         "86",
			colorMarkdownCodeForeground: "230",
			colorMarkdownCodeBackground: "236",
			colorMarkdownCodeBorder:     "62",
			colorMarkdownQuote:          "245",
			colorMarkdownQuoteBorder:    "244",
			colorPanelBorder:            "238",
			colorInputFocusedBorder:     "86",
			colorInputWaitingBorder:     "244",
			colorInputMultilineBorder:   "214",
			colorInputTerminal:          "#ff5ac8",
			colorSelectedProviderBg:     "62",
			colorSelectedProviderFg:     "231",
			colorUnselectedProvider:     "245",
			colorWizardTitle:            "229",
			colorWizardBorder:           "62",
			colorSelectionBackground:    "237",
			colorSelectionForeground:    "255",
			colorContextCache:           "214",
			colorContextUsed:            "111",
			colorContextFree:            "240",
			colorCursorNormalBright:     "#9fffd3",
			colorCursorTerminalBright:   "#ff8ddd",
		},
	}
}

// Hex 返回指定颜色角色对应的 lipgloss 颜色字符串。
func (c ColorManager) Hex(role colorRole) string {
	if c.palette == nil {
		c = NewColorManager()
	}
	return strings.ToLower(c.palette[role])
}

// LipglossColor 返回指定颜色角色对应的 lipgloss.Color。
func (c ColorManager) LipglossColor(role colorRole) lipgloss.Color {
	return lipgloss.Color(c.Hex(role))
}

// CursorColor 根据亮度和终端模式生成光标颜色。
func (c ColorManager) CursorColor(intensity float64, terminal bool) string {
	bright := colorCursorNormalBright
	if terminal {
		bright = colorCursorTerminalBright
	}
	return interpolateHexColor(c.Hex(colorTerminalBackground), c.Hex(bright), clamp01(intensity))
}

// cursorColor 使用当前默认颜色管理器生成光标颜色。
func cursorColor(intensity float64, terminal bool) string {
	return colorManager.CursorColor(intensity, terminal)
}

// interpolateHexColor 在两个十六进制颜色之间按比例插值。
func interpolateHexColor(from, to string, amount float64) string {
	fr, fg, fb := parseHexColor(from)
	tr, tg, tb := parseHexColor(to)
	return fmt.Sprintf(
		"#%02x%02x%02x",
		lerpInt(fr, tr, amount),
		lerpInt(fg, tg, amount),
		lerpInt(fb, tb, amount),
	)
}

// parseHexColor 将 #rrggbb 字符串解析为 RGB 分量。
func parseHexColor(color string) (int, int, int) {
	color = strings.TrimPrefix(color, "#")
	if len(color) != 6 {
		return 0, 0, 0
	}
	r, err := strconv.ParseInt(color[0:2], 16, 0)
	if err != nil {
		return 0, 0, 0
	}
	g, err := strconv.ParseInt(color[2:4], 16, 0)
	if err != nil {
		return 0, 0, 0
	}
	b, err := strconv.ParseInt(color[4:6], 16, 0)
	if err != nil {
		return 0, 0, 0
	}
	return int(r), int(g), int(b)
}

// lerpInt 对整数颜色分量做线性插值。
func lerpInt(from, to int, amount float64) int {
	return from + int(float64(to-from)*amount+0.5)
}

package bubble

import (
	"context"
	"fmt"
	tea "github.com/charmbracelet/bubbletea"
	"gocode/internal/model"
	"gocode/internal/settings"
	"gocode/internal/subagent"
	"os"
	"path/filepath"
	"strings"
	"time"
)

func commandArgs(invocation string) string {
	token := commandToken(invocation)
	return strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(invocation), token))
}

func (m *appModel) handleModelCommand(invocation string) tea.Cmd {
	args := strings.TrimSpace(commandArgs(invocation))
	switch args {
	case "":
		m.modelWizard = newModelWizard(m.currentModelConfig())
		m.pending = nil
	case "status":
		cfg := m.currentModelConfig()
		m.addEntry(transcriptEntry{
			kind:  entrySystem,
			title: "model",
			body:  fmt.Sprintf("provider=%s base=%s path=%s model=%s key=%s", cfg.Provider, cfg.APIBaseURL, cfg.APIPath, cfg.Model, cfg.APIKeyEnvName),
		})
	case model.ProviderCustom, model.ProviderDeepSeek:
		cfg, err := m.configForProvider(args)
		if err != nil {
			m.addEntry(transcriptEntry{kind: entryError, title: "model", body: err.Error()})
			return nil
		}
		m.applyModelConfigFromCommand(cfg)
	default:
		m.addEntry(transcriptEntry{kind: entryError, title: "model", body: fmt.Sprintf("unknown model command: %s", args)})
	}
	return nil
}

func (m *appModel) applyModelConfigFromCommand(cfg model.Config) {
	if m.modelConfig == nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "model", body: "model config controller is unavailable"})
		return
	}
	if saver, ok := m.modelConfig.(ModelConfigSaver); ok {
		if err := saver.SaveModelConfig(cfg); err != nil {
			m.addEntry(transcriptEntry{kind: entryError, title: "model", body: err.Error()})
			return
		}
	}
	if err := m.modelConfig.ApplyModelConfig(cfg); err != nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "model", body: err.Error()})
		return
	}
	m.addEntry(transcriptEntry{
		kind:  entrySystem,
		title: "model",
		body:  fmt.Sprintf("provider=%s base=%s path=%s model=%s key=%s", cfg.Provider, cfg.APIBaseURL, cfg.APIPath, cfg.Model, cfg.APIKeyEnvName),
	})
}

func (m *appModel) handleExportCommand(invocation string) {
	path, err := m.exportPath(commandArgs(invocation))
	if err != nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "export", body: err.Error()})
		return
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "export", body: err.Error()})
		return
	}
	content := exportTranscriptText(m.transcript)
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "export", body: err.Error()})
		return
	}
	if err := os.Chmod(path, 0o600); err != nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "export", body: err.Error()})
		return
	}
	m.addEntry(transcriptEntry{kind: entrySystem, title: "export", body: "conversation exported to " + path})
}

func (m appModel) exportPath(arg string) (string, error) {
	root, err := os.Getwd()
	if err != nil {
		return "", err
	}
	arg = strings.TrimSpace(arg)
	if arg == "" {
		name := "conversation-" + time.Now().Format("2006-01-02-150405") + ".txt"
		return filepath.Join(root, ".ccagent", "exports", name), nil
	}
	if !strings.HasSuffix(arg, ".txt") {
		arg = strings.TrimSuffix(arg, filepath.Ext(arg)) + ".txt"
	}
	target := arg
	if !filepath.IsAbs(target) {
		target = filepath.Join(root, target)
	}
	absRoot, err := filepath.Abs(root)
	if err != nil {
		return "", err
	}
	absTarget, err := filepath.Abs(target)
	if err != nil {
		return "", err
	}
	rel, err := filepath.Rel(absRoot, absTarget)
	if err != nil {
		return "", err
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("export path escapes workspace root: %s", arg)
	}
	return absTarget, nil
}

func exportTranscriptText(entries []transcriptEntry) string {
	var out strings.Builder
	for _, entry := range entries {
		if strings.TrimSpace(entry.body) == "" {
			continue
		}
		out.WriteString(entry.title)
		out.WriteString(":\n")
		out.WriteString(strings.TrimRight(entry.body, "\n"))
		out.WriteString("\n\n")
	}
	return out.String()
}

func (m *appModel) handleSubagentCommand(invocation string) tea.Cmd {
	req, err := m.parseSubagentCommand(invocation)
	if err != nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "subagent", body: err.Error()})
		return nil
	}
	if m.subagents == nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "subagent", body: "subagent controller is unavailable"})
		return nil
	}
	if req.RunMode == settings.RunModeBackground {
		task, err := m.subagents.Launch(m.ctx, req)
		if err != nil {
			m.addEntry(transcriptEntry{kind: entryError, title: "subagent", body: err.Error()})
			return nil
		}
		m.addEntry(transcriptEntry{kind: entrySystem, title: "subagent", body: renderTask(task)})
		return nil
	}
	if !m.queryGuard.StartModel() {
		m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: "assistant is already running"})
		return nil
	}
	m.syncRunningFlags()
	m.addEntry(transcriptEntry{kind: entrySystem, title: "subagent", body: "started sync subagent"})
	return runSubagentCmd(m.ctx, m.subagents, req)
}

func (m appModel) parseSubagentCommand(invocation string) (subagent.Request, error) {
	cfg := m.currentSettings()
	req := subagent.Request{
		ParentSessionID: m.sessionID,
		ContextMode:     cfg.Subagent.DefaultContextMode,
		RunMode:         cfg.Subagent.DefaultRunMode,
	}
	fields := strings.Fields(commandArgs(invocation))
	var prompt []string
	for _, field := range fields {
		switch field {
		case "--fork":
			req.ContextMode = settings.ContextModeFork
		case "--empty":
			req.ContextMode = settings.ContextModeEmpty
		case "--background":
			req.RunMode = settings.RunModeBackground
		case "--sync":
			req.RunMode = settings.RunModeSync
		default:
			prompt = append(prompt, field)
		}
	}
	req.Prompt = strings.Join(prompt, " ")
	req.Description = summarizeToolContent(req.Prompt)
	if strings.TrimSpace(req.Prompt) == "" {
		return req, fmt.Errorf("prompt is required")
	}
	return req, nil
}

func runSubagentCmd(ctx context.Context, controller SubagentController, req subagent.Request) tea.Cmd {
	return func() tea.Msg {
		result, err := controller.Run(ctx, req)
		return subagentFinishedMsg{result: result, err: err}
	}
}

func (m *appModel) handleTasksCommand() {
	if m.subagents == nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "tasks", body: "subagent controller is unavailable"})
		return
	}
	tasks := m.subagents.ListTasks()
	if len(tasks) == 0 {
		m.addEntry(transcriptEntry{kind: entrySystem, title: "tasks", body: "no subagent tasks"})
		return
	}
	lines := make([]string, 0, len(tasks))
	for _, task := range tasks {
		lines = append(lines, renderTask(task))
	}
	m.addEntry(transcriptEntry{kind: entrySystem, title: "tasks", body: strings.Join(lines, "\n\n")})
}

func (m appModel) statusText(sessionID string) string {
	cfg := m.currentSettings()
	modelCfg := m.currentModelConfig()
	taskCount := 0
	if m.subagents != nil {
		taskCount = len(m.subagents.ListTasks())
	}
	stats := m.contextStats()
	return fmt.Sprintf(
		"session: %s\nmodel: %s/%s\nsettings: context=%s run=%s meter=%s limit=%d\nqueue: %d\nsubagent tasks: %d\ncontext: used=%d cache=%d limit=%d",
		sessionID,
		modelCfg.Provider,
		modelCfg.Model,
		cfg.Subagent.DefaultContextMode,
		cfg.Subagent.DefaultRunMode,
		cfg.UI.ContextMeterLocation,
		cfg.UI.ContextLimitTokens,
		m.chatQueue.Len(),
		taskCount,
		stats.UsedTokens,
		stats.CacheTokens,
		stats.LimitTokens,
	)
}

func renderSubagentResult(result subagent.Result) string {
	return fmt.Sprintf("agent=%s transcript=%s\n%s", result.AgentID, result.TranscriptPath, strings.TrimSpace(result.Content))
}

func renderTask(task subagent.TaskSnapshot) string {
	line := fmt.Sprintf("%s status=%s context=%s transcript=%s", task.ID, task.Status, task.ContextMode, task.TranscriptPath)
	if task.Error != "" {
		line += "\nerror: " + task.Error
	}
	if task.Content != "" {
		line += "\nresult: " + summarizeToolContent(task.Content)
	}
	return line
}
